// Additional original editorial guides. These are not kitchen-tested recipes.
// Ingredient quantities are for the stated portions. Timings are estimates.
const safety={
 veg:['Serve freshly cooked; refrigerate perishable leftovers promptly. Check packaged ingredients for allergens.','现做现吃，易腐剩菜及时冷藏。检查包装食材的过敏原。'],
 chicken:['Chicken must reach 74°C / 165°F in the thickest part. Keep raw poultry and cooked food separate.','鸡肉最厚处须达到74°C，生鸡肉与熟食分开处理。'],
 pork:['Whole cuts of pork must reach 63°C / 145°F, then rest at least 3 minutes. Ground pork must reach 71°C / 160°F.','整块猪肉须达到63°C并静置至少3分钟；猪肉末须达到71°C。'],
 beef:['Whole cuts of beef must reach 63°C / 145°F and rest at least 3 minutes.','整块牛肉须达到63°C，并静置至少3分钟。'],
 egg:['Cook egg dishes to 71°C / 160°F. For boiled eggs, the white and yolk should be firm.','蛋类菜肴中心须达到71°C；煮蛋的蛋白与蛋黄应凝固。'],
 fish:['Fish must reach 63°C / 145°F in the thickest part. Remove bones carefully before serving.','鱼肉最厚处须达到63°C。食用前仔细检查鱼刺。'],
 shrimp:['Cook shrimp until the flesh is firm, opaque, and pearly. Avoid cross-contact with raw seafood.','虾肉应煮至紧实、不透明且呈珍珠色。避免与生海鲜交叉接触。'],
 rice:['Cool cooked rice promptly in shallow containers and refrigerate within 2 hours, or 1 hour above 32°C / 90°F. Reheat leftovers to 74°C / 165°F.','熟米饭用浅容器及时冷却，2小时内冷藏；环境超过32°C时1小时内冷藏。剩饭复热至74°C。']
};
function allergens(ingredients){
 const names=ingredients.map(x=>x[2]).join(' ').toLowerCase(),en=[],zh=[];
 const rules=[[/\beggs?\b/,'Egg','鸡蛋'],[/soy|tofu|doubanjiang|miso/,'Soy','大豆'],[/soy sauce|wheat|flour|noodles|wrappers/,'Wheat (check labels)','小麦（检查标签）'],[/sesame/,'Sesame','芝麻'],[/peanut/,'Peanut','花生'],[/shrimp/,'Crustacean shellfish','甲壳类海鲜'],[/fish fillet/,'Fish','鱼'],[/walnut|almond/,'Tree nuts','坚果']];
 for(const [pattern,e,z] of rules)if(pattern.test(names)){en.push(e);zh.push(z);}
 return [en.length?en.join(', '):'Check ingredient labels and cross-contact information.',zh.length?zh.join('、'):'检查食材标签和交叉接触信息。'];
}
export function recipe(x){
 const regions={sichuan:['Sichuan-inspired','川味'],northern:['Northern-style','北方风味'],shanghai:['Shanghai-style','上海风味'],cantonese:['Cantonese-inspired','粤式风味']};
 return {...x,pinyin:x.pin,minutes:x.prep+x.cook,servings:x.servings||2,vegetarian:!!x.vegetarian,spice:x.spice||0,region:x.region||regions[x.category]||['Home-style','家常菜'],category:x.category||'everyday',difficulty:x.difficulty||[x.cook>35?'Medium':'Easy',x.cook>35?'中等':'简单'],image:x.id+'.svg',allergens:x.allergens||allergens(x.ingredients),safety:x.safety||safety[x.protein]||safety.veg,
  steps:x.steps.map(([e,z])=>{const [et,...eb]=e.split('|'),[zt,...zb]=z.split('|');return [et,eb.join('|'),zt,zb.join('|')];})};
}
